  // تصویر خطی lon/lat ← درصد روی قاب نقشه. با چهار شهر شناخته‌شده کالیبره شده
  // (اهواز، آبادان، اندیمشک، بهبهان) و با لبه‌های مرز استان هم‌خوان است.
  var PROJECTION = { xScale: 34.26, xOffset: -1632.6, yScale: -31.83, yOffset: 1050.8 };

  function project(lat, lon) {
    return {
      x: Math.round((PROJECTION.xScale * lon + PROJECTION.xOffset) * 10) / 10,
      y: Math.round((PROJECTION.yScale * lat + PROJECTION.yOffset) * 10) / 10
    };
  }

